// neverError above means a rejected send (e.g. outside WhatsApp's 24-hour window, or
// Chatwoot itself down) lands here as a normal item instead of throwing — Chatwoot's
// error shape on a failed message create is typically { errors: ["..."] } or a plain
// { error: "..." }; not verified against a live rejection from this account, so this
// checks both and falls back to a generic message rather than silently swallowing an
// unrecognized shape.
const resp = $input.first().json;
const errText = Array.isArray(resp.errors) ? resp.errors.join(', ') : (resp.error || resp.message);
if (errText && !resp.id) {
  return [{ json: { error: String(errText) } }];
}

return [{ json: {
  id: resp.id,
  content: resp.content || '',
  message_type: resp.message_type,
  sender_type: resp.sender_type || (resp.sender && resp.sender.type) || 'agent',
  created_at: resp.created_at,
  status: resp.status || 'sent'
} }];
